args.command:
head -3 evidence/prior-run/session.jsonl; echo ---; tail -5 evidence/prior-run/session.jsonl | cut -c1-1000; echo ---; python3 - <<'PY'
import json
p='evidence/prior-run/session.jsonl'
for i,l in enumerate(open(p)):
    try: o=json.loads(l)
    except: continue
    if i<3: print(i, list(o.keys()), o.get('type'))
PY

python3 - > /tmp/prior_text.txt <<'PY'
import json
p='evidence/prior-run/session.jsonl'
for i,l in enumerate(open(p,encoding='utf-8')):
    o=json.loads(l)
    if o.get('type')=='assistant/message':
        d=o['data']; content=d.get('message',{}).get('content',[])
        parts=[]
        for c in content:
            if c.get('type')=='reasoning': parts.append('[reasoning] '+c.get('text',''))
            elif c.get('type')=='text': parts.append('[text] '+c.get('text',''))
        if parts:
            print(f'\n===== event {i} seq {o.get("seq")} step {d.get("step")}')
            print('\n'.join(parts))
PY
wc -l /tmp/prior_text.txt; sed -n '1,260p' /tmp/prior_text.txt

python3 - <<'PY'
import json
p='evidence/prior-run/session.jsonl'
for i,l in enumerate(open(p)):
 o=json.loads(l)
 if o.get('type')=='tool/call' and 480<=i<=505:
  print('\n### CALL',i); print(o['data'].get('arguments','')[:5000])
 if o.get('type')=='tool/result' and 480<=i<=505:
  print('\n### RESULT',i); print(str(o['data'].get('message',{}).get('content',''))[:5000])
PY

set -e
rm -rf /tmp/repro-case3 && mkdir -p /tmp/repro-case3/state
git clone -q /run/stage/world/evidence/basis.bundle /tmp/repro-case3/basis
git -C /tmp/repro-case3/basis fetch -q /run/stage/world/evidence/case-3/candidate.bundle 'HEAD:refs/heads/c3'
git -C /tmp/repro-case3/basis worktree add -q --detach /tmp/repro-case3/world c3
cp /run/stage/world/evidence/case-3/owners/*.sqlite /tmp/repro-case3/state/
cat > /tmp/repro-case3/profile.json <<'JSON'
