  "databases": {
    "orchestration": "/tmp/repro-case3/state/palimpsest.sqlite",
    "ordarium": "/tmp/repro-case3/state/ordarium.sqlite",
    "coordination": "/tmp/repro-case3/state/coordination.sqlite",
    "transportCursors": "/tmp/repro-case3/state/transport-cursors.sqlite",
    "projectJournal": "/tmp/repro-case3/state/journal.sqlite",
    "projectAssociations": "/tmp/repro-case3/state/associations.sqlite",
    "management": "/tmp/repro-case3/state/management.sqlite"
  }
}
