node --input-type=module -e '
import {launchDeployment,loadDeploymentProfile} from "/run/stage/world/dist/src/advanced.js";
const d=launchDeployment(loadDeploymentProfile("/tmp/repro-case3/profile.json"));
try {
 const s=d.installed.controller.status();
 const tool=d.installed.tools.find(t=>t.name==="palimpsest_work");
 const ctx={callId:"repro",rootCallId:"repro",arguments:{action:"readiness"},name:"palimpsest_work",signal:new AbortController().signal};
 const r=await tool.execute({action:"readiness"},ctx);
 console.log(JSON.stringify({head:s.headCommit,tasks:s.tasks.length,attempts:s.attempts.length,directOutcome:s.directOutcome,readiness:{action:r.action,reasons:r.reasons,next:r.next}},null,2));
} finally { await d.close(); }
' 2>&1 | tail -120

